--
-- Name: v_du_bao_webgis; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_du_bao_webgis AS
 SELECT d.ma_ban_ghi,
    d.thoi_gian,
    k.ten_khu_vuc,
    d.ma_chi_so,
    d.gia_tri,
    d.toa_do_diem,
    d.loai_nguon_du_lieu
   FROM (public.du_lieu_chi_so d
     JOIN public.khu_vuc k ON ((k.ma_khu_vuc = d.ma_khu_vuc)))
  WHERE ((d.loai_nguon_du_lieu)::text = ANY ((ARRAY['AI_FORECAST'::character varying, 'SIMULATION'::character varying])::text[]));


ALTER VIEW public.v_du_bao_webgis OWNER TO postgres;

--
-- Name: v_so_sanh_model; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_so_sanh_model AS
 SELECT t.ma_training,
    m.ten_model,
    t.ma_chi_so_muc_tieu,
    mm.mae,
    mm.rmse,
    mm.r2,
    mm.mape
   FROM ((public.training_run t
     JOIN public.model m ON ((m.ma_model = t.ma_model)))
     JOIN public.model_metric mm ON (((mm.ma_training = t.ma_training) AND ((mm.tap_danh_gia)::text = 'TEST'::text))));


